public class Solution
{
    private Int128 ONE = 1;
    public int LengthOfLongestSubstring(string s)
    {
        int Convert(char ch) => ch - ' ';
        Int128 mask = 0;
        int l = 0, r = 0, output = 0;
        while (r < s.Length)
        {
            Int128 temp = mask ^ (ONE << Convert(s[r]));
            if (temp < mask)
            {
                while (s[l] != s[r])
                {
                    mask ^= ONE << Convert(s[l]);
                    l++;
                }
                mask ^= ONE << Convert(s[l]);
                l++;
            }
            else
            {
                mask = temp;
                output = Math.Max(output, r - l + 1);
                r++;
            }
        }

        return output;
    }
}

public class Solution {
      public double FindMedianSortedArrays(int[] nums1, int[] nums2)
      {
         if (nums1.Length <= 0 && nums2.Length == 1)
            {
                return nums2[0];
            }
            if (nums2.Length <= 0 && nums1.Length == 1)
            {
                return nums1[0];
            }

            var m = nums1.Length;
            var n = nums2.Length;
            if (m > n)
            {
                return FindMedianSortedArrays(nums2, nums1);
            }
            var total = m + n;
            var half = (total + 1) / 2;
            var left = 0;
            var right = m;
            var result = 0.0;
            while (left <= right)
            {
                var i = left + (right - left) / 2;
                var j = half - i;
                var left1 = (i > 0) ? nums1[i - 1] : int.MinValue;
                var right1 = (i < m) ? nums1[i] : int.MaxValue;
                var left2 = (j > 0) ? nums2[j - 1] : int.MinValue;
                var right2 = (j < n) ? nums2[j] : int.MaxValue;

                if (left1 <= right2 && left2 <= right1)
                {
                    if (total % 2 == 0)
                    {
                        result = (Math.Max(left1, left2) + Math.Min(right1, right2)) / 2.0;
                    }
                    else
                    {
                        result = Math.Max(left1, left2);
                    }
                    break;
                }
                else if (left1 > right2)
                {
                    right = i - 1;
                }
                else
                {
                    left = i + 1;
                }
            }
            return result;
      }
}

public class Solution {
    public string LongestPalindrome(string s) {
        var l = 0;
        var h = 0;
        var len1 = 0;
        for (var i = 0; i < s.Length; i++) {
            len1 = Math.Max(lengthOfPalindrome(s, i, i),
                                lengthOfPalindrome(s, i, i + 1));

            if(len1 > h-l) {
                l = i - (len1 - 1)  / 2;
                h = i +  len1       / 2;
            }
        }
        return s.Substring(l, h - l + 1);

    }

    public int lengthOfPalindrome(String s, int L, int H) {

        while(L >= 0 && H < s.Length && s[L] == s[H]) {
            L--;
            H++;
        }
        return H - L - 1;

    }
}

public class Solution {
    public int Reverse(int x) {
        int rev = 0;

        while(x != 0) {
            var digit = x % 10;
            x = x / 10;
            if(rev > Int32.MaxValue / 10 ||
               // since max value is 2,147,483,647,
               // last digit greater than 7 will overflow
              (rev == Int32.MaxValue / 10 && digit > 7))
                return 0;

            if (rev < Int32.MinValue/10 ||
                // since min value is  -2,147,483,648
                (rev == Int32.MinValue / 10 && digit < -8))
                return 0;

            rev = rev * 10 + digit;
        }

        return rev;
    }
}

public class Solution
{
    // T: O(M*N) | S: O(M*N)
    public bool IsMatch(string s, string p)
    {
        // Top down
        var cache = new Dictionary<(int, int), bool>();

        bool dfs(int i, int j)
        {
            if (cache.ContainsKey((i, j)))
                return cache[(i, j)];
            if (i >= s.Length && j >= p.Length)
                return true;
            if (j >= p.Length)
                return false;

            var match = i < s.Length && (s[i] == p[j] || p[j] == '.');
            if (j + 1 < p.Length && p[j + 1] == '*')
            {
                cache.TryAdd((i, j), false);
                cache[(i, j)] = (match && dfs(i + 1, j)) || //use *
                  dfs(i, j + 2); //dont use *
                return cache[(i, j)];
            }

            if (match)
            {
                cache.TryAdd((i, j), false);
                cache[(i, j)] = dfs(i + 1, j + 1);
                return cache[(i, j)];

            }

            cache.TryAdd((i, j), false);
            cache[(i, j)] = false;
            return cache[(i, j)];

        }

        return dfs(0, 0);
    }
}

public class Solution {
    public int MaxArea(int[] height) {
        int res = 0, area = 0, left = 0, right = height.Length-1;

        while (left < right){

            area = (Math.Min(height[left], height[right])) * (right - left);
            res = Math.Max(area, res);

            if(height[left] < height[right]){
                left++;
            }else{
                right--;
            }

        }
        return res;
    }
}

public class Solution {
    public string LongestCommonPrefix(string[] strs) {
        string result = strs[0];
        int charIndex = 0;

        //finding minimum string length  - that could be max common prefix
        int maxCharIndex = strs[0].Length;
        for (int i = 1; i < strs.Length; ++i) {
            maxCharIndex = Math.Min(maxCharIndex, strs[i].Length);
        }

        while (charIndex < maxCharIndex) {
            char prevChar = strs[0][charIndex];
            for (int i = 1; i < strs.Length; ++i) {
                if (prevChar == strs[i][charIndex]) {
                    continue;
                }
                return result.Substring(0, charIndex);
            }
            ++charIndex;
            result += prevChar;
        }
        return result.Substring(0, charIndex);
    }
}

public class Solution {
    public IList<IList<int>> ThreeSum(int[] nums) {
        List<IList<int>> res = new List<IList<int>>();
        int left, right;
        Array.Sort(nums);

        for(int i = 0; i < nums.Length; i++){
            if(i > 0 && nums[i] == nums[i-1]){
                continue;
            }

            left = i+1;
            right = nums.Length-1;

            while(left < right){
                if(nums[i] + nums[left] + nums[right] > 0){
                    right--;
                }else if(nums[i] + nums[left] + nums[right] < 0){
                    left++;
                }else {
                    res.Add(new List<int> {nums[i], nums[left], nums[right]});
                    left++;
                    while(nums[left] == nums[left-1] && left < right){
                        left++;
                    }
                }
            }
        }
        return res;
    }
}

public class Solution {
  public IList<string> LetterCombinations(string digits)
        {
            var lettersMap = new Dictionary<char, string>
            {
                {'2', "abc"},
                {'3', "def"},
                {'4', "ghi"},
                {'5', "jkl"},
                {'6', "mno"},
                {'7', "pqrs"},
                {'8', "tuv"},
                {'9', "wxyz"}
            };

            var result = new List<string>();

            if (!string.IsNullOrEmpty(digits))
                Backtrack(result, digits, lettersMap, "", 0);

            return result;
        }

        void Backtrack(List<string> result, string digits, Dictionary<char, string> lettersMap, string curString, int start)
        {
            if (curString.Length == digits.Length)
            { result.Add(curString); return; }

            foreach (var c in lettersMap[digits[start]])
            {
                Backtrack(result, digits, lettersMap, curString + c, start + 1);
            }
        }
}

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     public int val;
 *     public ListNode next;
 *     public ListNode(int val=0, ListNode next=null) {
 *         this.val = val;
 *         this.next = next;
 *     }
 * }
 */
public class Solution {
    public ListNode RemoveNthFromEnd(ListNode head, int n) {
        var dummy = new ListNode(0, head);
        var left = dummy;
        var right = head;

        while(n > 0) {
            right = right.next;
            n--;
        }

        while(right != null) {
            left = left.next;
            right = right.next;
        }

        // delete
        left.next = left.next.next;
        return dummy.next;
    }
}

public class Solution {
    public bool IsValid(string s) {
        var stack = new Stack<char>();
        var pairs = new Dictionary<char, char>() {
            [')'] = '(',
            [']'] = '[',
            ['}'] = '{'
        };

        foreach (char c in s) {
            if (!pairs.ContainsKey(c)) {
                stack.Push(c);
            } else if (stack.Count == 0 || stack.Pop() != pairs[c]) {
                return false;
            }
        }

        return stack.Count == 0;
    }
}

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     public int val;
 *     public ListNode next;
 *     public ListNode(int val=0, ListNode next=null) {
 *         this.val = val;
 *         this.next = next;
 *     }
 * }
 */
public class Solution {
    public ListNode MergeTwoLists(ListNode list1, ListNode list2) {
        var dummy = new ListNode();
        var tail = dummy;

        while(list1 is not null && list2 is not null) {
            if(list1.val < list2.val) {
                tail.next = list1;
                list1 = list1.next;
            }
            else {
                tail.next = list2;
                list2 = list2.next;
            }
            tail = tail.next;
        }

        if(list1 is not null)
            tail.next = list1;
        else if(list2 is not null)
            tail.next = list2;

        return dummy.next;
    }
}

public class Solution {
    public IList<string> GenerateParenthesis(int n) {
        var result = new List<string>();
        var seq = new StringBuilder();

        void backtrack(int open, int close) {
            if(seq.Length == n * 2) {
                result.Add(seq.ToString());
                return;
            }

            if(open < n) {
                seq.Append("(");
                backtrack(open + 1, close);
                seq.Remove(seq.Length - 1, 1);
            }
            if(close < open) {
                seq.Append(")");
                backtrack(open, close + 1);
                seq.Remove(seq.Length - 1, 1);
            }

        }

        backtrack(0, 0);

        return result;
    }
}

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     public int val;
 *     public ListNode next;
 *     public ListNode(int val=0, ListNode next=null) {
 *         this.val = val;
 *         this.next = next;
 *     }
 * }
 */

public class Solution {
    public ListNode MergeKLists(ListNode[] lists) {
        if (lists.Length == 0)
        {
            return null;
        }

        while (lists.Length > 1)
        {
            var mergedLists = new ListNode[(lists.Length + 1) / 2];
            for (int i = 0; i < lists.Length; i += 2)
            {
                var l1 = lists[i];
                var l2 = (i + 1 < lists.Length) ? lists[i + 1] : null;
                mergedLists[i/2] = (MergeLists(l1, l2));
            }
            lists = mergedLists;
        }

        return lists[0];
    }

    public ListNode MergeLists(ListNode l1, ListNode l2)
    {
        var sorted = new ListNode();
        var current = sorted;

        while (l1 != null && l2 != null)
        {
            if (l1.val <= l2.val)
            {
                current.next = l1;
                l1 = l1.next;
            }
            else
            {
                current.next = l2;
                l2 = l2.next;
            }
            current = current.next;
        }

        if (l1 != null)
        {
            current.next = l1;
        } else
        {
            current.next = l2;
        }

        return sorted.next;
    }
}

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     public int val;
 *     public ListNode next;
 *     public ListNode(int val=0, ListNode next=null) {
 *         this.val = val;
 *         this.next = next;
 *     }
 * }
 */
public class Solution
{
    public ListNode ReverseKGroup(ListNode head, int k)
    {
        var dummy = new ListNode(0, head);
        var groupPrev = dummy;
        var groupNext = dummy;

        while (true)
        {
            var kth = getKth(groupPrev, k);
            if (kth == null)
                break;

            groupNext = kth.next;

            // reverse group
            var prev = kth.next;
            var curr = groupPrev.next;

            while (curr != groupNext)
            {
                var temp = curr.next;
                curr.next = prev;
                prev = curr;
                curr = temp;
            }

            var tmp = groupPrev.next;
            groupPrev.next = kth;
            groupPrev = tmp;
        }

        return dummy.next;
    }

    private ListNode getKth(ListNode curr, int k)
    {
        while (curr != null && k > 0)
        {
            curr = curr.next;
            k -= 1;
        }

        return curr;
    }
}

public class Solution {
    public int RemoveDuplicates(int[] nums) {
        int l = 1, r = 1;
        while (r < nums.Length) {
            if (nums[r] != nums[r - 1]) {
                nums[l] = nums[r];
                ++l;
            }
            ++r;
        }
        return l;
    }
}

public class Solution {
    public int RemoveElement(int[] nums, int val) {
        if (nums == null || nums.Length == 0)
            return 0;

        int i = 0;

        for (int j = 0; j < nums.Length; j++)
        {
            while (j < nums.Length && nums[j] == val)
                j++;

            if (j < nums.Length)
                nums[i++] = nums[j];
        }

        return i;
    }
}

public class Solution
{
    public int StrStr(string haystack, string needle)
    {
        if (needle.Length > haystack.Length) return -1;

        int l = 0;
        int r = needle.Length - 1;

        while (r < haystack.Length)
        {
            bool areEqual = true;
            for (int i = l, j = 0; i <= r; i++, j++)
            {
                if (haystack[i] != needle[j])
                {
                    areEqual = false;
                    break;
                }
            }

            if (areEqual)
            {
                return l;
            }

            l++;
            r++;
        }

        return -1;
    }
}

public class Solution {
    public int Search(int[] nums, int target) {
        int low = 0;
        int high = nums.Length - 1;

        while(low <= high) {
            var mid = (low + high) / 2;

            if(nums[mid] == target) {
                return mid;
            } else if(nums[low] <= nums[mid]) {
                if(target > nums[mid] ||  target < nums[low])
                    low = mid + 1;
                else high = mid - 1;
            } else {
                if(target < nums[mid] || target > nums[high])
                    high = mid - 1;
                else low = mid + 1;
            }
        }


        return -1;
    }
}

public class Solution {
public int[] SearchRange(int[] nums, int target)
        {
            int first = -1, last = -1;

            first = searchEle(nums, target, true);
            if (first == -1)
                return new int[] { first, last };

            last = searchEle(nums, target, false);


            return new int[] { first, last };
        }

        public int searchEle(int[] nums, int target, bool isStart)
        {
  int n = nums.Length;
            int start = 0, end = nums.Length - 1;

            while (start <= end)
            {
                int mid = (start + end )/ 2;
                if (nums[mid] == target)
                {
                    if (isStart)
                    {
                        if (mid == start || nums[mid - 1] != target)
                        {
                            return mid;
                        }
                        end = mid - 1;
                    }
                    else
                    {
                        if (mid == end || nums[mid + 1] != target)
                        {
                            return mid;
                        }
                        start = mid + 1;
                    }
                }
                else if (nums[mid] > target)
                    end = mid - 1;
                else
                    start = mid + 1;

            }
            return -1;
        }
}

public class Solution
{
    public int SearchInsert(int[] nums, int target)
    {
        int leftPointer = 0;
        int rightPointer = nums.Length - 1;
        while (leftPointer <= rightPointer)
        {
            int mid = leftPointer + (rightPointer - leftPointer) / 2;
            if (nums[mid] == target)
            {
                return mid;
            }
            else if (nums[mid] < target)
            {
                leftPointer = mid + 1;
            }
            else
            {
                rightPointer = mid - 1;
            }
        }
        return leftPointer;
    }
}

public class Solution {
    public bool IsValidSudoku(char[][] board) {
        var rows = new Dictionary<int, HashSet<char>>();
        var cols = new Dictionary<int, HashSet<char>>();
        var squares = new Dictionary<(int, int), HashSet<char>>();

        for(var r = 0; r < 9; r++) {
            rows[r] = new HashSet<char>();
            for(var c = 0; c < 9; c++) {
                if(!cols.ContainsKey(c)) cols[c] = new HashSet<char>();
                if(!squares.ContainsKey((r/3, c/3)))
                    squares[(r/3, c/3)] = new HashSet<char>();

                if(board[r][c] == '.') continue;


                if(rows[r].Contains(board[r][c]) ||
                  cols[c].Contains(board[r][c]) ||
                  squares[(r / 3, c / 3)].Contains(board[r][c]))
                   return false;

                rows[r].Add(board[r][c]);
                cols[c].Add(board[r][c]);
                squares[(r / 3, c / 3)].Add(board[r][c]);
            }
        }

        return true;
    }
}

public class Solution {
    IList<IList<int>> result = new List<IList<int>>();
    public void backtrack(int index, List<int> path, int total, int[] candidates, int target) {
        if(total == target) {
            result.Add(path.ToList());
            return;
        }

        if(total > target || index >= candidates.Length) return;

        path.Add(candidates[index]);
        backtrack(index,
                  path,
                  total + candidates[index],
                  candidates,
                  target);

        path.Remove(path.Last());

        backtrack(index + 1,
                  path,
                  total,
                  candidates,
                  target);

    }
    public IList<IList<int>> CombinationSum(int[] candidates, int target) {
        backtrack(0, new List<int>(), 0, candidates, target);
        return result;
    }
}

public class Solution
{
    //T: O(2^T), where T is target
    public IList<IList<int>> CombinationSum2(int[] candidates, int target)
    {

        var result = new List<IList<int>>();
        Array.Sort(candidates);

        void dfs(int pos, Stack<int> current, int target)
        {
            if (target == 0)
            {
                result.Add(current.ToList());
            }
            if (target <= 0)
            {
                return;
            }

            var prev = -1;

            for (var i = pos; i < candidates.Length; i++)
            {
                if (candidates[i] == prev)
                    continue;

                current.Push(candidates[i]);
                dfs(i + 1, current, target - candidates[i]);
                current.Pop();
                prev = candidates[i];
            }

        }

        dfs(0, new Stack<int>(), target);
        return result;
    }
}

public class Solution
{

    public int Trap(int[] height)
    {

        if (height is null || height.Length == 0) return 0;

        int left = 0, right = height.Length - 1;
        int leftMax = height[left], rightMax = height[right];
        var result = 0;

        while (left < right)
        {
            if (leftMax < rightMax)
            {
                left++;
                leftMax = Math.Max(leftMax, height[left]);
                result += leftMax - height[left];
            }
            else
            {
                right--;
                rightMax = Math.Max(rightMax, height[right]);
                result += rightMax - height[right];
            }
        }

        return result;
    }
}

public class Solution
{
    //T: O(m*n)  | S: O(m+n)
    public string Multiply(string num1, string num2)
    {
        if (string.Equals(num1, "0") || string.Equals(num2, "0"))
            return "0";
        var m = num1.Length;
        var n = num2.Length;

        var result = new int[m + n];

        num1 = Reverse(num1);
        num2 = Reverse(num2);

        for (var i1 = 0; i1 < num1.Length; i1++)
        {
            for (var i2 = 0; i2 < num2.Length; i2++)
            {

                var digit = (num1[i1] - '0') * (num2[i2] - '0');
                result[i1 + i2] += digit;
                result[i1 + i2 + 1] += (result[i1 + i2]) / 10;
                result[i1 + i2] = (result[i1 + i2]) % 10;
            }
        }

        Array.Reverse(result);
        var i = 0;
        while (i < result.Length && result[i] == 0)
        {
            i++;
        }

        var str = new StringBuilder();
        for (; i < result.Length; i++)
        {
            //Console.WriteLine(result[i]);
            str.Append(result[i]);
        }
        return str.ToString();

    }

    private string Reverse(string str)
    {
        var array = str.ToCharArray();
        Array.Reverse(array);
        return new string(array);
    }
}

public class Solution {
    public int Jump(int[] nums) {
        int left = 0, right = 0, res = 0;

        while (right < nums.Length - 1) {
            int maxJump = 0;
            for (int i = left; i <= right; i++) {
                maxJump = Math.Max(maxJump, i + nums[i]);
            }
            left = right + 1;
            right = maxJump;
            res++;
        }
        return res;
    }
}

public class Solution
{
    public IList<IList<int>> Permute(int[] nums)
    {
        var result = new List<IList<int>>();
        PermuteRecurse(result, nums, 0);
        return result;
    }

    private void PermuteRecurse(List<IList<int>> res, int[] arr, int start)
    {
        if (start == arr.Length)
        {
            var list = arr.Select(t => (t)).ToList();
            res.Add(list);
            return;
        }

        for (var i = start; i < arr.Length; i++)
        {
            (arr[start], arr[i]) = (arr[i], arr[start]);
            PermuteRecurse(res, arr, start + 1);
            (arr[start], arr[i]) = (arr[i], arr[start]);
        }
    }
}

public class Solution
{
    public IList<IList<int>> PermuteUnique(int[] nums)
    {
        Array.Sort(nums);
        var output = new List<IList<int>>();
        Backtrack(output, nums.ToList(), []);
        return output;
    }

    private void Backtrack(List<IList<int>> output, List<int> nums, List<int> current)
    {
        if (nums.Count == 0)
        {
            output.Add(new List<int>(current));
        }
        else
        {
            for (int i = 0; i < nums.Count; i++)
            {
                if (i > 0 && nums[i] == nums[i - 1])
                {
                    continue;
                }
                int num = nums[i];
                current.Add(num);
                nums.Remove(num);
                Backtrack(output, nums, current);
                nums.Insert(i, num);
                current.RemoveAt(current.Count - 1);
            }
        }
    }
}

public class Solution {
    public void Rotate(int[][] matrix) {
        (int left, int right) = (0, matrix.Length -1);

        while(left < right) {
            var limit = right - left;
            for(var i = 0; i < limit; i++) {
                (int top, int bottom) = (left, right);

                // save the top left position
                var topLeft = matrix[top][left + i];

                // put the bottom left value to the top left position
                matrix[top][left + i] = matrix[bottom - i][left];

                // put the bottom right value to the bottom left position
                matrix[bottom - i][left] = matrix[bottom][right - i];

                // put the top right value to the bottom right position
                matrix[bottom][right - i] = matrix[top + i][right];

                // put the saved top left value to the top right position
                matrix[top + i][right] = topLeft;


            }

            left++;
            right--;
        }

        return;
    }
}

