public class Solution
{
    public double MyPow(double x, long n)
    {
        var result = helper(x, Math.Abs(n));
        return n > 0 ? result : 1 / result;
    }

    private double helper(double x, long n)
    {
        if (x == 0) return 0;
        if (n == 0) return 1;

        var result = helper(x, n / 2);
        result = result * result;
        return n % 2 == 1 ? x * result : result;
    }
}

public class Solution {
     public IList<IList<string>> SolveNQueens(int n)
        {
            var result = new List<IList<string>>();
            IList<StringBuilder> board = new List<StringBuilder>();
            for (int i = 0; i < n; i++)
            {
                board.Add(new StringBuilder(n));
                board[i].Append('.', n);

            }
            backtrackingNQueens(n, 0, board, result, new HashSet<(int i, int j)>(), new HashSet<(int i, int j)>(), new HashSet<(int i, int j)>());
            return result;
        }

        private void backtrackingNQueens(int n, int row, IList<StringBuilder> board, List<IList<string>> result, HashSet<(int i, int j)> col, HashSet<(int i, int j)> positiveDiag, HashSet<(int i, int j)> negativeDiag)
        {
            if (n == 0)
            {
                result.Add(board.Select(s => s.ToString()).ToList());
                return;
            }
            if (row == board.Count) return;

            for (int c = 0; c < board.Count; c++)
            {
                (int i, int j) column = (0, c);
                int m = Math.Min(row, c);
                (int i, int j) diag1 = (row - m, c - m);
                m = Math.Min(row, board.Count - 1 - c);
                (int i, int j) diag2 = (row - m, c + m);

                if (col.Contains(column) || positiveDiag.Contains(diag1) ||
                   negativeDiag.Contains(diag2)) continue;

                col.Add(column);
                positiveDiag.Add(diag1);
                negativeDiag.Add(diag2);


                board[row][c] = 'Q';
                backtrackingNQueens(n - 1, row + 1, board, result, col, positiveDiag, negativeDiag);

                board[row][c] = '.';
                col.Remove(column);
                positiveDiag.Remove(diag1);
                negativeDiag.Remove(diag2);
            }
        }

}

public class Solution
{
    public int TotalNQueens(int n)
    {
        List<int> col = new List<int>(n);
        List<int> diag1 = new List<int>(n);
        List<int> diag2 = new List<int>(n);
        int output = 0;
        Backtrack(ref output, col, diag1, diag2, n, 0, n);
        return output;
    }

    private void Backtrack(ref int output, List<int> col, List<int> diag1, List<int> diag2, int grid_size, int row, int queens_left)
    {
        if(queens_left == 0)
        {
            output++;
        }
        else
        {
            for(int c = 0; c < grid_size; c++)
            {
                if(CanPlace(col, diag1, diag2, row, c))
                {
                    Place(col, diag1, diag2, row, c);
                    Backtrack(ref output, col, diag1, diag2, grid_size, row + 1, queens_left - 1);
                    Remove(col, diag1, diag2, row, c);
                }
            }
        }
    }
    private bool CanPlace(List<int> col, List<int> diag1, List<int> diag2, int r, int c)
    {
        return !col.Contains(c) && !diag1.Contains(r + c) && !diag2.Contains(r - c);
    }
    private void Place(List<int> col, List<int> diag1, List<int> diag2, int r, int c)
    {
        col.Add(c);
        diag1.Add(r + c);
        diag2.Add(r - c);
    }
    private void Remove(List<int> col, List<int> diag1, List<int> diag2, int r, int c)
    {
        col.Remove(c);
        diag1.Remove(r + c);
        diag2.Remove(r - c);
    }
}

