public class Solution {
    public bool SearchMatrix(int[][] matrix, int target) {
        int ROWS = matrix.Length;
        int COLS = matrix[0].Length;
        int top = 0, bot = ROWS - 1;
        int row = 0;

        while(top <= bot) {
            row = (top + bot) / 2;
            if(target > matrix[row][COLS-1]) top = row + 1;
            else if (target < matrix[row][0]) bot = row - 1;
            else break;
        }

        if (top > bot) return false;

        int l = 0, r = COLS - 1;

        while (l <= r) {
            int m = (l + r) / 2;
            if (target > matrix[row][m]) l = m + 1;
            else if (target < matrix[row][m]) r = m - 1;
            else return true;
        }

        return false;
    }
}

public class Solution {
    public void SortColors(int[] nums) {
        int low = 0;
        int high = nums.Length - 1;
        int mid = 0;

        while (mid <= high) {
            switch (nums[mid]) {
                case 0:
                    int temp0 = nums[low];
                    nums[low] = nums[mid];
                    nums[mid] = temp0;
                    low++;
                    mid++;
                    break;
                case 1:
                    mid++;
                    break;
                case 2:
                    int temp2 = nums[mid];
                    nums[mid] = nums[high];
                    nums[high] = temp2;
                    high--;
                    break;
            }
        }
    }
}

public class Solution
{

    public string MinWindow(string s, string t)

    {
        if (string.IsNullOrEmpty(t)) return string.Empty;

        var countT = new Dictionary<char, int>();
        var window = new Dictionary<char, int>();

        foreach (var c in t)
        {
            AddCharToDictionary(c, countT);
        }

        var have = 0;
        var need = countT.Count;
        var left = 0;
        var res = new[] { -1, -1 };
        var resultLength = int.MaxValue;
        for (var right = 0; right < s.Length; right++)
        {
            var c = s[right];
            AddCharToDictionary(c, window);

            if (countT.ContainsKey(c) && window[c] == countT[c]) have++;

            while (have == need)
            {
                // update our result
                var windowSize = right - left + 1;
                if (windowSize < resultLength)
                {
                    res = new[] { left, right };
                    resultLength = windowSize;
                }

                // pop from the left of our window
                window[s[left]]--;
                if (countT.ContainsKey(s[left]) && window[s[left]] < countT[s[left]])
                {
                    have--;
                }

                left++;
            }
        }

        return resultLength == int.MaxValue
           ? string.Empty
           : s.Substring(res[0], res[1] - res[0] + 1);
    }

    private void AddCharToDictionary(char c, IDictionary<char, int> dict)
    {
        if (dict.ContainsKey(c)) dict[c]++;
        else dict.Add(c, 1);
    }
}

public class Solution
{
    public IList<IList<int>> Combine(int n, int k)
    {
        var output = new List<IList<int>>();
        Backtrack(output, [], n, k, 1);
        return output;
    }

    private void Backtrack(List<IList<int>> output, List<int> current, int n, int k, int index)
    {
        if (current.Count == k)
        {
            output.Add(new List<int>(current));
        }
        else
        {
            for (int i = index; i <= n; i++)
            {
                current.Add(i);
                Backtrack(output, current, n, k, i + 1);
                current.RemoveAt(current.Count - 1);
            }
        }
    }
}

public class Solution {
    private List<int> subset = new List<int>();
    private List<IList<int>> result = new List<IList<int>>();
    private void backtrack(int i, int[] nums) {
        if(i >= nums.Length) {
            result.Add(new List<int>(subset));
            return;
        }
        subset.Add(nums[i]);
        backtrack(i + 1, nums);
        subset.Remove(nums[i]);
        backtrack(i + 1, nums);

    }
