public class Solution {
    public int NumDecodings(string s) {
        List<int> dp = Enumerable.Repeat(1, s.Length + 1).ToList();

        for(var i = s.Length - 1; i >= 0; i--) {
            if (s[i] == '0')
                dp[i] = 0;
            else
                dp[i] = dp[i + 1];

            if (i + 1 < s.Length && (
                s[i] == '1' ||
                (s[i] == '2' && "0123456".Contains(s[i + 1]))
            ))
                dp[i] += dp[i + 2];
        }

        return dp[0];
    }
}

public class Solution
{
    public IList<string> RestoreIpAddresses(string s)
    {
        if (s.Length < 4) return [];

        var output = new List<string>();
        Backtrack(output, new StringBuilder(), s, null, 0, 0);
        return output;
    }
    private void Backtrack(List<string> output, StringBuilder sb, ReadOnlySpan<char> input, int? octet, int octet_count, int index)
    {
        if (octet_count > 4) return;

        if (sb.Length - 3 == input.Length)
        {
            output.Add(sb.ToString());
        }
        else
        {
            int max_index = Math.Min(index + 3, input.Length);
            for (int i = index; i < max_index; i++)
            {
                if (octet.HasValue)
                {
                    if (octet.Value == 0 || octet > 25 || octet == 25 && input[i] > '5') break;

                    octet *= 10;
                    octet += input[i] - '0';
                }
                else
                {
                    octet = input[i] - '0';
                }
                string octet_string = sb.Length == 0 ? octet.Value.ToString() : $".{octet.Value}";
                sb.Append(octet_string);
                Backtrack(output, sb, input, null, octet_count + 1, i + 1);
                sb.Remove(sb.Length - octet_string.Length, octet_string.Length);
            }
        }
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     public int val;
 *     public TreeNode left;
 *     public TreeNode right;
 *     public TreeNode(int val=0, TreeNode left=null, TreeNode right=null) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
public class Solution {
    public IList<int> InorderTraversal(TreeNode root) {
        // return InorderTraversalRecursive(root).ToList();
        return InorderTraversalIterative(root).ToList();
    }

    // Time: O(n)
    // Space: O(n)
    private IEnumerable<int> InorderTraversalRecursive(TreeNode node) {
        if (node == null) {
            return Enumerable.Empty<int>();
        }

        return InorderTraversalRecursive(node.left)
            .Append(node.val)
            .Concat(InorderTraversalRecursive(node.right));
    }

    // Time: O(n)
    // Space: O(n)
    private IEnumerable<int> InorderTraversalIterative(TreeNode node) {
        List<int> result = new();
        Stack<TreeNode> stack = new();
        while (node != null || stack.Any()) {
            while (node != null) {
                stack.Push(node);
                node = node.left;
            }
            node = stack.Pop();
            result.Add(node.val);
            node = node.right;
        }
        return result;
    }
}

public class Solution
{
    //T:O(M*N)
    public bool IsInterleave(string s1, string s2, string s3)
    {
        if (s1.Length + s2.Length != s3.Length)
            return false;

        var dp = new bool[s1.Length + 1, s2.Length + 1];
        dp[s1.Length, s2.Length] = true;

        for (var i = s1.Length; i >= 0; i--)
        {
            for (var j = s2.Length; j >= 0; j--)
            {
                if (i < s1.Length && s1[i] == s3[i + j] && dp[i + 1, j])
                {
                    dp[i, j] = true;
                }
                if (j < s2.Length && s2[j] == s3[i + j] && dp[i, j + 1])
                {
                    dp[i, j] = true;
                }
            }

        }

        return dp[0, 0];
    }

}

