public class Solution {

int maxPathSum = Int32.MinValue;

        public int MaxPathSum(TreeNode root)
        {
            DfsMaxPathSum(root);
            return maxPathSum;
        }

        private int DfsMaxPathSum(TreeNode root)
        {
            if (root == null)
                return 0;

            int leftMax = DfsMaxPathSum(root.left),
                rightMax = DfsMaxPathSum(root.right),
                currentMax = 0;

            currentMax = Math.Max(currentMax, Math.Max(leftMax + root.val, rightMax + root.val));
            maxPathSum = Math.Max(maxPathSum, leftMax + root.val + rightMax);

            return currentMax;
        }
}

public class Solution {
    public bool IsPalindrome(string s) {
        int left = 0;
        int right = s.Length - 1;

        while (left < right) {
            if (!char.IsLetterOrDigit(s[left])) {
                left++;
            } else if (!char.IsLetterOrDigit(s[right])) {
                right--;
            } else {
                if (char.ToLower(s[left]) != char.ToLower(s[right])) {
                    return false;
                }
                left++;
                right--;
            }
        }
        return true;
    }
}

public class Solution
{
    //T: O(N^2*M) where N is the length of the word, M is total no. of words
    //S: O(N^2*M) where N is the length of the word, M is total no. of words
    public int LadderLength(string beginWord, string endWord, IList<string> wordList)
    {
        if (!wordList.Contains(endWord))
        {
            return 0;
        }

        var nei = new Dictionary<string,
          HashSet<string>>();
        if (!wordList.Contains(beginWord))
            wordList.Add(beginWord);

        foreach (var word in wordList)
        {
            for (var j = 0; j < word.Length; j++)
            {
                var pattern = word.Substring(0, j) + "*" + word.Substring(j + 1);
                nei.TryAdd(pattern, new HashSet<string>());
                nei[pattern].Add(word);
            }
        }

        foreach (var neiWord in nei.Keys)
        {
            foreach (var val in nei[neiWord])
            {
                Console.WriteLine("neiWord : " + neiWord + " val : " + val);
            }
        }

        var visited = new HashSet<string>();
        visited.Add(beginWord);

        var queue = new Queue<string>();
        queue.Enqueue(beginWord);

        var result = 1;

        while (queue.Count > 0)
        {
            var count = queue.Count;
            for (var i = 0; i < count; i++)
            {
                var item = queue.Dequeue();
                if (string.Equals(item, endWord))
                    return result;

                for (var j = 0; j < item.Length; j++)
                {
                    var pattern = item.Substring(0, j) + "*" + item.Substring(j + 1);
                    foreach (var neiWord in nei[pattern])
                    {
                        if (!visited.Contains(neiWord))
                        {
                            queue.Enqueue(neiWord);
                            visited.Add(neiWord);

                        }
                    }

                }

            }
            result += 1;
        }

        return 0;
    }
}

public class Solution {
    public int LongestConsecutive(int[] nums) {
        if (nums.Length < 2) return nums.Length;

        var set = new HashSet<int>(nums);
        var longest = 0;
        foreach (var n in set)
        {
            if (!set.Contains(n-1))
            {
                var length = 0;
                while (set.Contains(n+length))
                {
                    length++;
                    longest = Math.Max(longest, length);
                }
            }
        }

        return longest;
    }
}

public class Solution {
    public void Solve(char[][] board) {
        var n = board.Length;

        if (n == 0) return;
        var m = board[0].Length;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if ((i == 0 || j == 0 || i == n - 1 || j == m - 1) && board[i][j] == 'O') {
                    CaptureDfs(board, i, j);
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] == 'O') {
                    board[i][j] = 'X';
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] == 'T') {
                    board[i][j] = 'O';
                }
            }
        }
    }

    private void CaptureDfs(char[][] board, int x, int y) {
        var n = board.Length;
        var m = board[0].Length;

        if (x >= n || x < 0 || y >= m || y < 0) {
            return;
        }

        if (board[x][y] == 'T' || board[x][y] == 'X') return;

        board[x][y] = 'T';
        CaptureDfs(board, x+1, y);
        CaptureDfs(board, x-1, y);
        CaptureDfs(board, x, y+1);
        CaptureDfs(board, x, y-1);

    }
}

public class Solution
{
    //O(N.2^N)
    public IList<IList<string>> Partition(string s)
    {
        var result = new List<IList<string>>();
        var stack = new List<string>();

        void dfs(int i)
        {
            if (i >= s.Length)
            {
                result.Add(stack.ToList());
                return;
            }

            for (var j = i; j < s.Length; j++)
            {
                if (IsPalindrome(s, i, j))
                {
                    stack.Add(s.Substring(i, j - i + 1));
                    dfs(j + 1);
                    stack.RemoveAt(stack.Count - 1);
                }
            }

        }

        dfs(0);

        return result;
    }

    public bool IsPalindrome(string s, int l, int r)
    {
        while (l < r)
        {
            if (s[l] != s[r])
                return false;
            l++;
            r--;
        }

        return true;
    }
}

