        stack.Push(val);
        int min = Math.Min(val, minStack.Count != 0 ? minStack.Peek() : val);
        minStack.Push(min);
    }

    public void Pop() {
        stack.Pop();
        minStack.Pop();
    }

    public int Top() {
        return stack.Peek();
    }

    public int GetMin() {
        return minStack.Peek();
    }
}

public class Solution {
    public int[] TwoSum(int[] numbers, int target) {
        // Using 2 pointers. Since sorted, if l+r > target, decrease r.
        // Else if l+r < target, increase l. Else, result is found.
        int left = 0, right = numbers.Length - 1;

        while (left < right) {
            int sum = numbers[left] + numbers[right];
            if (sum > target) {
                right--;
            } else if (sum < target) {
                left++;
            } else {
                return new int[] {left + 1, right + 1};
            }
        }

        return new int[0];
    }
}

public class Solution {

    private const int _ASCII_BASE = 64;

    public string ConvertToTitle(int columnNumber)
    {
        StringBuilder sb = new StringBuilder();

        while (columnNumber > 0)
        {
            int rest = columnNumber % 26;
            rest = rest == 0 ? 26 : rest;

            sb.Insert(0, (char)(rest + _ASCII_BASE));

            columnNumber -= rest;
            columnNumber /= 26;
        }

        return sb.ToString();
    }
}

