public class Solution {
    public int MaxProfit(int[] prices) {
        int sold = 0, rest = 0, hold = Int32.MinValue;

        for (int i = 0; i < prices.Length; i++) {
            int prevSold = sold;
            sold = hold + prices[i];
            hold = Math.Max(hold, rest - prices[i]);
            rest = Math.Max(rest, prevSold);
        }
        return Math.Max(sold, rest);
    }
}

public class Solution
{
    // T: O(N^3) | S: O(N^2)
    public int MaxCoins(int[] nums)
    {
        var n = nums.Length + 2;
        var memo = new int[n, n];
        //Array.Fill(memo, -1);
        var arr = new int[n];
        arr[0] = 1;
        arr[^1] = 1;
        for (int i = 1; i < n - 1; i++) arr[i] = nums[i - 1];

        return MaxCoins(arr, memo, 1, n - 2);
    }

    private int MaxCoins(int[] arr, int[,] memo, int start, int end)
    {
        if (start > end)
            return 0;

        if (memo[start, end] != 0)
            return memo[start, end];

        memo[start, end] = 0;
        for (var i = start; i < end + 1; i++)
        {
            var coins = arr[start - 1] * arr[i] * arr[end + 1];
            coins += MaxCoins(arr, memo, start, i - 1) + MaxCoins(arr, memo, i + 1, end);
            memo[start, end] = Math.Max(memo[start, end], coins);
        }

        return memo[start, end];
    }

}

public class Solution {
    public IList<int> CountSmaller(int[] nums) {

            var sortedNums = new List<int>();
            var result = new int[nums.Length];

            for (int i = nums.Length - 1; i >= 0; i--)
            {
                int left = 0;
                int right = sortedNums.Count;

                while (left < right)
                {
                    var mid = left + (right - left) / 2;
                    if (sortedNums[mid] >= nums[i]) right = mid;
                    else left = mid + 1;
                }

                result[i] = left;
                sortedNums.Insert(left, nums[i]);
            }

            return result;
    }
}

public class Solution {
    public int CoinChange(int[] coins, int amount) {
        var dp = Enumerable.Repeat(amount + 1, amount + 1).ToArray();

        dp[0] = 0;

        for(var a = 1; a <= amount; a++) {
            foreach(var c in coins) {
                if(a - c >= 0) {
                    dp[a] = Math.Min(dp[a], 1 + dp[a-c]);
                }
            }
        }

        return dp[amount] == amount + 1
            ? -1
            : dp[amount];
    }
}

public class Solution {
     private int noOfConnectedComponents = 0;
        private int[] rank;

        public int CountComponents(int n, int[][] edges)
        {
            if (n == 0)
                return noOfConnectedComponents;

            noOfConnectedComponents = n;
            rank = new int[n];

            for (int i = 0; i < n; i++)
                rank[i] = i;

            foreach (int[] edge in edges)
                Union(edge[0], edge[1]);

            return noOfConnectedComponents;
        }

        private void Union(int x, int y)
        {
            int p1 = Find(x), p2 = Find(y);

            if (p1 != p2)
            {
                rank[p1] = p2;
                noOfConnectedComponents--;
            }
        }

        private int Find(int n)
        {
            if (rank[n] != n)
                rank[n] = Find(rank[n]);

            return rank[n];
        }
}

public class Solution
{
    //T: O(N*M) | S: O(N*M) || has complex topological sort order and hence memoization.
    public int LongestIncreasingPath(int[][] matrix)
    {

        var rows = matrix.Length;
        var cols = matrix[0].Length;
        var maxValue = int.MinValue;

        var dictionary = new Dictionary<(int, int), int>();

        int dfs(int i, int j, int previous)
        {
            if (i >= matrix.Length || j >= matrix[0].Length || i < 0 || j < 0 || matrix[i][j] <= previous)
                return 0;

            if (dictionary.ContainsKey((i, j)))
                return dictionary[(i, j)];


            var value = 1 + Math.Max(
                                    Math.Max(
                                        Math.Max(dfs(i + 1, j, matrix[i][j]), dfs(i - 1, j, matrix[i][j])),
                                        dfs(i, j - 1, matrix[i][j])),
                                    dfs(i, j + 1, matrix[i][j]));

            dictionary.TryAdd((i, j), 0);
            dictionary[(i, j)] = value;

            maxValue = Math.Max(maxValue, value);
            return value;
        }

        for (var i = 0; i < rows; i++)
        {
            for (var j = 0; j < cols; j++)
            {
                dfs(i, j, -1);
            }
        }
        return maxValue;
    }
}

public class Solution {
public IList<string> FindItinerary(IList<IList<string>> tickets)
        {
            var map = new Dictionary<string, List<string>>();
            foreach (var ticket in tickets)
            {
                if (!map.TryGetValue(ticket[0], out var adj))
                {
                    adj = new List<string>();
                    map.Add(ticket[0], adj);
                }
                adj.Add(ticket[1]);
            }

            foreach (var adj in map.Values)
            {
                adj.Sort(Comparer<string>.Create((a, b) => string.Compare(b, a)));
            }

            var res = new Stack<string>();
            DfsVisit(map, "JFK", res);
            return res.ToList();
        }

        private void DfsVisit(Dictionary<string, List<string>> map, string src, Stack<string> ans)
        {
            if (map.TryGetValue(src, out var adj))
            {
                while (adj.Count > 0)
                {
                    var next = adj.Last();
                    adj.RemoveAt(adj.Count - 1);
                    DfsVisit(map, next, ans);
                }
            }
            ans.Push(src);
        }
}

