public class Solution {
    public int CharacterReplacement(string s, int k) {
        int left = 0, maxLength = 0;
        int mostFrequentLetterCount = 0; // Count of most frequent letter in the window
        int[] charCounts = new int[26]; // Counts per letter

        for (int right = 0; right < s.Length; right++) {
            charCounts[s[right] - 'A']++;
            mostFrequentLetterCount = Math.Max(mostFrequentLetterCount, charCounts[s[right] - 'A']);

            int lettersToChange = (right - left + 1) - mostFrequentLetterCount;
            if (lettersToChange > k) { // Window is invalid, decrease char count and move left pointer
                charCounts[s[left] - 'A']--;
                left++;
            }

            maxLength = Math.Max(maxLength, (right - left + 1));
        }
        return maxLength;
    }
}

public class Solution
{
    public int EraseOverlapIntervals(int[][] intervals)
    {
        var sortedIntervals = intervals.Clone() as int[][];
        Array.Sort(sortedIntervals, (a, b) => a[0] - b[0]);

        var result = 0;
        var prevEnd = sortedIntervals[0][1];
        for (var i = 1; i < sortedIntervals.Length; i++)
        {

            var curr = sortedIntervals[i];

            if (prevEnd > curr[0])
            {
                result++;
                prevEnd = Math.Min(prevEnd, curr[1]);
            }
            else
            {
                prevEnd = curr[1];
            }
        }

        return result;
    }
}

public class Solution
{

    public IList<int> FindAnagrams(string s, string p)
    {
        List<int> res = new List<int>();

        int pSize = p.Length;
        int sSize = s.Length;

        if (pSize > sSize)
        {
            return res;
        }

        Dictionary<char, int> pHash = new Dictionary<char, int>();
        Dictionary<char, int> sHash = new Dictionary<char, int>();

        foreach (char c in p)
        {
            int tmp;
            pHash.TryGetValue(c, out tmp);
            pHash[c] = tmp + 1;
        }

        for (int x = 0; x < pSize; x++)
        {
            char c = s[x];
            int tmp;
            sHash.TryGetValue(c, out tmp);
            sHash[c] = tmp + 1;
        }

        if (compareDict(pHash, sHash))
        {
            res.Add(0);
        }

        int i = 1;
        int j = i + pSize - 1;

        while (j < sSize)
        {
            sHash[s[i - 1]]--;

            int tmp;
            sHash.TryGetValue(s[j], out tmp);
            sHash[s[j]] = tmp + 1;

            if (compareDict(pHash, sHash))
            {
                res.Add(i);
            }

            i++;
            j++;
        }

        return res;
    }

    public bool compareDict(Dictionary<char, int> d1, Dictionary<char, int> d2)
    {
        foreach (var i in d1)
        {
            if (d2.ContainsKey(i.Key) && i.Value == d2[i.Key])
            {
                continue;
            }
            else
            {
                return false;
            }
        }

        return true;
    }
}

