public class Solution {
    public int[] NextGreaterElement(int[] nums1, int[] nums2) {

        Dictionary<int,int> dic = new Dictionary<int,int>();
        Stack<int> stack = new Stack<int>();
        foreach(var num in nums2)
        {
            while(stack.Count > 0 && num > stack.Peek())
                dic.Add(stack.Pop(),num);

            stack.Push(num);
        }

        int[] res = new int[nums1.Length];
        for(int i = 0; i < nums1.Length; i++)
            res[i] = dic.ContainsKey(nums1[i])? dic[nums1[i]] : -1;

        return res;
    }
}

public class Solution
{
    public enum Direction
    {
        Left,
        Right
    }

    public struct Pos
    {
        public int i;
        public int j;

        public Pos(int i, int j)
        {
            this.i = i;
            this.j = j;
        }
    }

    public static bool OutOfRange(int[][] mat, int i, int j)
    {
        if (mat.Length == 0 || mat[0].Length == 0) return true;

        if (i >= mat.Length || j >= mat[0].Length) return true;

        if (i < 0 || j < 0) return true;

        return false;
    }

    public static bool MoveForward(ref Pos pos, ref Direction direction, int[][] mat)
    {
        var i = pos.i;
        var j = pos.j;
        var maxI = mat.Length - 1;
        var maxJ = mat[0].Length - 1;

        if (direction == Direction.Left)
        {
            i += 1;
            j -= 1;
        }
        else
        {
            i -= 1;
            j += 1;
        }

        if (OutOfRange(mat, i, j))
        {
            direction = direction == Direction.Right ? Direction.Left : Direction.Right;

            i = pos.i;
            j = pos.j;

            if (direction == Direction.Left)
            {
                if (j < maxJ) j += 1;
                else i += 1;
            }
            else
            {
                if (i < maxI) i += 1;
                else j += 1;
            }
        }

        pos = new Pos(i, j);

        return !OutOfRange(mat, i, j);
    }

    public int[] FindDiagonalOrder(int[][] mat)
    {
        int[] result = new int[mat.Length * mat[0].Length];
        var pos = new Pos(0, 0);
        var direction = Direction.Right;
        var i = 0;

        do
        {
            result[i++] = mat[pos.i][pos.j];
        }
        while (MoveForward(ref pos, ref direction, mat));

        return result;
    }
}

public class Solution
{
    // memoization reduces T from O(M^N) to O(M.N) where M- is no. of coins, N is amount
    public int Change(int amount, int[] coins)
    {
        var mem = new Dictionary<(int, int), int>();

        int dfs(int index, int a)
        {
            if (a == amount)
                return 1;
            if (a > amount)
                return 0;
            if (index == coins.Length)
                return 0;
            if (mem.ContainsKey((index, a)))
                return mem[(index, a)];

            mem[(index, a)] = dfs(index, a + coins[index]) + dfs(index + 1, a);
            return mem[(index, a)];

        }

        return dfs(0, 0);
    }
}

public class Solution
{
    public bool CheckSubarraySum(int[] nums, int k)
    {
        var remainder = new Dictionary<int, int>();
        remainder.Add(0, -1);
        var total = 0;
        for (var i = 0; i < nums.Length; i++)
        {
            total += nums[i];
            var r = total % k;
            if (!remainder.ContainsKey(r))
                remainder.Add(r, i);
            else if (i - remainder[r] > 1)
                return true;
        }
        return false;
    }
}

