public class Solution
{
    public int SubarraySum(int[] nums, int k)
    {
        Dictionary<int, int> prefixToCounts = new Dictionary<int, int>();
        prefixToCounts.Add(0, 1);

        int sum = 0;
        int res = 0;

        for (int i = 0; i < nums.Length; i++)
        {
            sum += nums[i];
            int diff = sum - k;

            prefixToCounts.TryGetValue(diff, out int count);

            res += count;

            if (prefixToCounts.ContainsKey(sum))
            {
                prefixToCounts[sum] += 1;
                continue;
            }

            prefixToCounts.Add(sum, 1);
        }

        return res;
    }
}

public class Solution
{
    public bool CheckInclusion(string s1, string s2)
    {
        {
            if (s1.Length > s2.Length) return false;

            var s1Count = Enumerable.Repeat(0, 26).ToArray();
            var s2Count = Enumerable.Repeat(0, 26).ToArray();

            for (var i = 0; i < s1.Length; i++)
            {
                s1Count[s1[i] - 'a']++;
                s2Count[s2[i] - 'a']++;
            }

            var matches = 0;
            for (var i = 0; i < 26; i++)
            {
                if (s1Count[i] == s2Count[i]) matches++;
            }

            var left = 0;
            for (var right = s1.Length; right < s2.Length; right++)
            {
                if (matches == 26) return true;

                var index = s2[right] - 'a';
                s2Count[index]++;
                if (s1Count[index] == s2Count[index])
                {
                    matches++;
                }
                else if (s1Count[index] + 1 == s2Count[index])
                {
                    matches--;
                }

                index = s2[left] - 'a';
                s2Count[index]--;
                if (s1Count[index] == s2Count[index])
                {
                    matches++;
                }
                else if (s1Count[index] - 1 == s2Count[index])
                {
                    matches--;
                }

                left++;
            }

            return matches == 26;
        }
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     public int val;
 *     public TreeNode left;
 *     public TreeNode right;
 *     public TreeNode(int val=0, TreeNode left=null, TreeNode right=null) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
public class Solution {
    public bool IsSubtree(TreeNode root, TreeNode subRoot) {
        if (root == null) return root == subRoot;
        if (root.val == subRoot?.val && IsSameTree(root, subRoot)) return true;

        return IsSubtree(root.left, subRoot) || IsSubtree(root.right, subRoot);
    }

    public bool IsSameTree(TreeNode p, TreeNode q) {
        if (p == null || q == null) return p == q;

        return p.val == q.val
            && IsSameTree(p.left, q.left)
            && IsSameTree(p.right, q.right);
    }
}

