public class Solution
{
    private PriorityQueue<FreqClass, int> pq;
    private Dictionary<char, int> dictionary;
    public int LeastInterval(char[] tasks, int n)
    {
        // Count tasks in the array
        if (n == 0)
            return tasks.Length;
        dictionary = new Dictionary<char, int>();
        foreach (var task in tasks)
        {
            if (dictionary.ContainsKey(task))
            {
                dictionary[task]++;
            }
            else
                dictionary.Add(task, 1);
        }


        pq = new PriorityQueue<FreqClass, int>(new MaxHeap());

        var time = 0;

        AddItemsToPQ();


        while (pq.Count > 0)
        {
            var list = new List<FreqClass>();
            var cnt = 0;
            for (var i = 0; i < n + 1; i++)
            {
                if (pq.Count > 0)
                {
                    var item = pq.Dequeue();
                    cnt++;
                    //Console.WriteLine($"Dequeued {item.Task} with frequency : {item.Frequency}");
                    item.Frequency--;
                    if (item.Frequency > 0)
                        list.Add(item);
                }
            }

            for (var i = 0; i < list.Count; i++)
            {
                var item = list[i];
                //Console.WriteLine($"Enqueued {item.Task} with frequency : {item.Frequency}");
                pq.Enqueue(item, item.Frequency);
            }

            time += pq.Count == 0 ? cnt : n + 1;
            //Console.WriteLine($"Done with iteration, current time: {time}");
        }

        return time;
    }

    private void AddItemsToPQ()
    {
        foreach (var keyValuePair in dictionary)
        {
            pq.Enqueue(new FreqClass(keyValuePair.Value, 0, keyValuePair.Key), keyValuePair.Value);
        }
    }

    public class MaxHeap : IComparer<int>
    {
        public int Compare(int x, int y)
        {
            return y - x;
        }
    }

    public class FreqClass
    {
        public int Frequency;
        public int IdleTime;
        public char Task;

        public FreqClass(int frequency, int idleTime, char task)
        {
            Frequency = frequency;
            IdleTime = idleTime;
            Task = task;
        }
    }
}

public class Solution {
    public int CountSubstrings(string s) {
        var count = 0;

        for(var i = 0; i < s.Length; i++) {
            count += getPalindromeCount(s, i, i);
            count += getPalindromeCount(s, i, i + 1);
        }

        return count;
    }

    public int getPalindromeCount(string s, int l, int r) {
        var count = 0;

        while(l >=0 && r < s.Length && s[l] == s[r]) {
            count++;
            l--;
            r++;
        }
        return count;
    }
}

public class Solution
{
    public bool CheckPossibility(int[] nums)
    {
        bool isChanged = false;

        for (int i = 0; i < nums.Length - 1; i++)
        {
            if (nums[i] <= nums[i + 1]) continue;

            if (isChanged) return false;

            if (i == 0 || nums[i + 1] >= nums[i - 1])
            {
                nums[i] = nums[i + 1];
            }
            else
            {
                nums[i + 1] = nums[i];
            }

            isChanged = true;
        }

        return true;
    }
}

public class Solution
{
    //T: O(N) , S: O(1)
    public bool CheckValidString(string s)
    {
        var leftMax = 0;
        var leftMin = 0;

        foreach (var ch in s)
        {
            if (ch == '(')
            {
                leftMin++;
                leftMax++;
            }
            else if (ch == ')')
            {
                leftMax--;
                leftMin--;
            }
            else
            {
                leftMin--;
                leftMax++;
            }

            if (leftMax < 0)
                return false;

            if (leftMin < 0)
                leftMin = 0;

        }

        return leftMin == 0;
    }
}

public class Solution
{
    public bool ValidPalindrome(string s)
    {
        int leftPointer = 0;
        int rightPointer = s.Length - 1;
        while (leftPointer < rightPointer)
        {
            if (s[leftPointer] != s[rightPointer])
            {
                return IsPalindrome(s, leftPointer + 1, rightPointer) || IsPalindrome(s, leftPointer, rightPointer - 1);
            }
            leftPointer++;
            rightPointer--;
        }
        return true;
    }
