public class MyHashMap
{
    private class LinkedListNode
    {
        public LinkedListNode(int key, int val, LinkedListNode next)
        {
            this.Key = key;
            this.Val = val;
            this.Next = next;
        }

        public int Key { get; set; }
        public int Val { get; set; }
        public LinkedListNode Next { get; set; }
    }

    public MyHashMap()
    {
        Map = new LinkedListNode[10000];
    }

    public int Hash(int key)
    {
        return key % Map.Length;
    }

    public void Put(int key, int value)
    {
        int index = Hash(key);
        if (Map[index] == null)
            Map[index] = new LinkedListNode(key, value, null);
        else
        {
            LinkedListNode node = Map[index];
            while (true)
            {
                if (node.Key == key)
                {
                    node.Val = value;
                    return;
                }
                if (node.Next == null)
                    break;
                else
                    node = node.Next;
            }
            node.Next = new LinkedListNode(key, value, null);
        }
    }

    public int Get(int key)
    {
        int index = Hash(key);
        LinkedListNode node = Map[index];
        if (node != null)
        {
            while (true)
            {
                if (node.Key == key)
                    return node.Val;

                if (node.Next == null)
                    break;
                else
                    node = node.Next;
            }
        }

        return -1;
    }

    public void Remove(int key)
    {
        int index = Hash(key);
        LinkedListNode node = Map[index];
        if (node == null)
            return;
        if (node.Key == key)
        {
            Map[index] = node.Next;
            node = null;
            return;
        }
        while (node.Next != null)
        {
            if (node.Next.Key == key)
            {
                node.Next = node.Next.Next;
                return;
            }

            node = node.Next;
        }
    }

    private LinkedListNode[] Map { get; set; }
}

public class Solution {
    public int PivotIndex(int[] nums) {
        int total = nums.Sum();

        int leftSum = 0;

        for (int i = 0; i < nums.Length; i++)
        {
            if (leftSum == total - leftSum - nums[i])
            {
                return i;
            }

            leftSum += nums[i];
        }
        return -1;
    }
}

public class Solution
{
    public int[] DailyTemperatures(int[] temperatures)
    {
        var result = new int[temperatures.Length];
        Array.Fill(result, 0);
        var stack = new Stack<int>();

        for (var i = 0; i < temperatures.Length; i++)
        {
            var t = temperatures[i];
            while (stack.Any() && temperatures[stack.Peek()] < t)
            {
                var prev = stack.Pop();
                result[prev] = i - prev;
            }
            stack.Push(i);
        }

        return result;
    }
}

public class Solution {
    public int NetworkDelayTime(int[][] times, int n, int k) {
      List<(int node, int weight)>[] adjList = new List<(int node, int weight)>[n + 1];

            for (var i = 0; i <= n; i++)
            {
                adjList[i] = new List<(int node, int wht)>();
            }

            foreach (var time in times)
            {
                adjList[time[0]].Add((time[1], time[2]));
            }

            int[] visited = new int[n + 1];
            Array.Fill(visited, 0);
            PriorityQueue<int, int> queue = new();

            queue.Enqueue(k, 0);
            int res = 0;
            while (queue.TryDequeue(out int node, out int weight))
            {
                if (visited[node] == 1) continue;
                visited[node] = 1;
                res = Math.Max(res, weight);
                foreach (var adj in adjList[node])
                {
                    var totalWT = weight + adj.weight;
                    queue.Enqueue(adj.node, totalWT);
                }
            }

            int? visitedCount = visited.Where(e => e == 1)?.Count();
            return visitedCount == n ? res : -1;
    }
}

public class Solution {
    public int MinCostClimbingStairs(int[] cost) {
        // return topDown(cost);
        return bottomUp(cost);
    }

    private int topDown(int[] cost) {
        var l = cost.Length;

        for(var i = 2; i < l; i ++) {
            cost[i] += Math.Min(cost[i - 1], cost[i - 2]);
        }

        return Math.Min(cost[l - 1], cost[l - 2]);
    }

    private int bottomUp(int[] cost) {

        for(var i = cost.Length - 3; i >= 0; i--) {
            cost[i] += Math.Min(cost[i + 1], cost[i + 2]);
        }

        return Math.Min(cost[0], cost[1]);
    }
}

public class Solution {
    public int OpenLock(string[] deadends, string target)
        {
            const string start = "0000";

            var deadEnds = deadends.ToHashSet();
            var visited = new HashSet<string>();
            if (deadEnds.Contains(start) || deadends.Contains(target)) return -1;

            Queue<string> q = new Queue<string>(new[] { start });
            visited.Add(start);
            int res = 0;
            while (q.Count > 0)
            {
                int queueCnt=q.Count;
                for (int i = 0; i < queueCnt; i++)
                {
                    var curr = q.Dequeue();
                    if (curr == target) return res;
                    foreach (var nei in GetNeighbors(curr))
                    {
                        if (!visited.Contains(nei) && !deadends.Contains(nei))
                        {
                            q.Enqueue(nei);
                            visited.Add(nei);
                        }
                    }
                }
                res++;
            }
            return -1;
        }

        private List<string> GetNeighbors(string s)
        {
            var result = new List<string>();
            for (int i = 0; i < s.Length; i++)
            {
                var charAr1 = s.ToCharArray();
                charAr1[i] = charAr1[i] == '9' ? '0' : (char)((int)charAr1[i] + 1);
                result.Add(new string(charAr1));
                var charAr2 = s.ToCharArray();
                charAr2[i] = charAr2[i] == '0' ? '9' : (char)((int)charAr2[i] - 1);
                result.Add(new string(charAr2));
            }
            return result;
        }
}

