public class Solution {
    PriorityQueue<(int, int), int> pq;
        private HashSet<(int, int)> visited;
        public int SwimInWater(int[][] grid)
        {
            int n = grid.Length;
            pq = new PriorityQueue<(int, int), int>();
            visited = new HashSet<(int, int)>();
            pq.Enqueue((0, 0), grid[0][0]);
            while (pq.TryDequeue(out var nei, out var priority))
            {
                int r = nei.Item1;
                int c = nei.Item2;
                visited.Add((r, c));

                if (r == n - 1 && c == n - 1) return priority;
                EnQueue(r + 1, c, grid, priority);
                EnQueue(r - 1, c, grid, priority);
                EnQueue(r, c + 1, grid, priority);
                EnQueue(r, c - 1, grid, priority);
            }
            return -1;
        }

        private void EnQueue(int r, int c, int[][] grid, int preCost)
        {
            if (r >= grid.Length || r < 0) return;
            if (c >= grid.Length || c < 0) return;
            if (visited.Contains((r, c))) return;

            pq.Enqueue((r, c), Math.Max(preCost, grid[r][c]));
        }
}

public class Solution
{
    //Bellman ford algo - T: O(K. E) & S: O(V)
    public int FindCheapestPrice(int n, int[][] flights, int src, int dst, int k)
    {
        var prices = new int[n];
        Array.Fill(prices, int.MaxValue);
        prices[src] = 0;

        for (var time = 0; time < k + 1; time++)
        {
            var tempPrices = prices.Clone() as int[];

            foreach (var item in flights)
            {
                var s = item[0];
                var d = item[1];
                var p = item[2];
                if (prices[s] == int.MaxValue)
                {
                    continue;
                }
                if (prices[s] + p < tempPrices[d])
                {
                    tempPrices[d] = prices[s] + p;
                }
            }
            prices = tempPrices;
        }

        return (prices[dst] == int.MaxValue) ? -1 : prices[dst];
    }
}

public class Solution
{
    //Same problem as #1296. Divide Array in Sets of K Consecutive Numbers
    //T: O(logN) for min heap, N is for all the items-> so overall O(NlogN)
    public bool IsNStraightHand(int[] hand, int groupSize)
    {
        if (hand.Length % groupSize != 0)
            return false;


        var dictionary = new Dictionary<int, int>();
        var minHeap = new PriorityQueue<int, int>();
        foreach (var item in hand)
        {
            dictionary.TryAdd(item, 0);
            dictionary[item]++;
        }

        // heapify is linear algorithm
        foreach (var key in dictionary.Keys)
            minHeap.Enqueue(key, key);

        while (minHeap.Count > 0)
        {
            var first = minHeap.Peek();

            for (var i = first; i < first + groupSize; i++)
            {
                if (!dictionary.ContainsKey(i))
                    return false;

                dictionary[i]--;
                if (dictionary[i] == 0)
                    if (i != minHeap.Peek())
                        return false;
                    else
                        minHeap.Dequeue();
            }

        }

        return true;

    }
}

public class Solution
{
    public int CarFleet(int target, int[] position, int[] speed)
    {
        var pair = new (int, int)[position.Length];
        for (var i = 0; i < position.Length; i++)
        {
            pair[i] = (position[i], speed[i]);
        }

        var stack = new Stack<double>();
        foreach (var (p, s) in pair.OrderByDescending(i => i.Item1))
        {
            stack.Push((target - p) / (double)s);
            if (stack.Count >= 2 && stack.Peek() <= stack.Skip(1).First())
            {
                stack.Pop();
            }
        }

        return stack.Count;
    }
}

public class Solution
{
    public int MinEatingSpeed(int[] piles, int h)
    {
        int left = 1, right = piles.Max();
        var result = right;

        while (left <= right)
        {
            var mid = left + (right - left) / 2;
            long hours = 0;
            foreach (var pile in piles)
            {
                hours += (int)Math.Ceiling(pile / (double)mid);
            }

            if (hours <= h)
            {
                result = Math.Min(result, mid);
                right = mid - 1;
            }
            else
            {
                left = mid + 1;
            }
        }

        return result;
    }
}

