 *     }
 * }
 */
public class Solution
{
    public bool IsCompleteTree(TreeNode root)
    {
        Queue<TreeNode> queue = new Queue<TreeNode>();
        queue.Enqueue(root);

        bool nullFound = false;

        while (queue.Any())
        {
            TreeNode node = queue.Dequeue();

            if (node is null)
            {
                nullFound = true;
                continue;
            }

            if (nullFound)
            {
                return false;
            }

            queue.Enqueue(node.left);
            queue.Enqueue(node.right);
        }

        return true;
    }
}

