public class Solution {
  public int OrangesRotting(int[][] grid)
        {
            if (grid == null || grid[0].Length == 0)
                return 0;

            int r = grid.Length, c = grid[0].Length, fresh = 0, time = 0;

            Queue<(int, int)> q = new Queue<(int, int)>();

            for (int i = 0; i < r; i++)
            {
                for (int j = 0; j < c; j++)
                {
                    if (grid[i][j] == 1)
                        fresh++;
                    else if (grid[i][j] == 2)
                    {
                        q.Enqueue((i, j));
                    };
                }
            }

            if (fresh == 0)
                return 0;

            int[,] dir = new int[,] { { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 } };
            while (q.Any())
            {
                time++;
                int size = q.Count;
                for (int i = 0; i < size; i++)
                {
                    var curr = q.Dequeue();
                    for (int j = 0; j < 4; j++)
                    {
                        int row = curr.Item1 + dir[j, 0];
                        int col = curr.Item2 + dir[j, 1];

                        if (row >= 0 && row < r && col >= 0 && col < c && grid[row][col] == 1)
                        {
                            grid[row][col] = 2;
                            q.Enqueue((row, col));
                            fresh--;
                        }
                    }
                }
            }

            return fresh == 0 ? time - 1 : -1;
        }}

public class Solution
{
    private PriorityQueue<int, int> pq;

    // T: O(NLogN)
    public int LastStoneWeight(int[] stones)
    {
        pq = new PriorityQueue<int, int>(new MaxHeapComparer());

        AddStones(stones);
        ComputeLastStoneWeight();

        return pq.Count == 0 ? 0 : pq.Dequeue();
    }


    private void AddStones(int[] stones)
    {
        foreach (var stone in stones)
        {
            // T: Heapify is O(N) for every enqueued item
            pq.Enqueue(stone, stone);
        }
    }

    // T: O(NLogN), to get max value its O(LogN) and we perform this for N items => O(NLogN)
    private void ComputeLastStoneWeight()
    {
        while (pq.Count > 1)
        {
            var y = pq.Dequeue();
            var x = pq.Dequeue();

            if (x != y)
            {
                var diff = y - x;
                pq.Enqueue(diff, diff);
            }
        }
    }

    public class MaxHeapComparer : IComparer<int>
    {
        public int Compare(int x, int y)
        {
            return y - x;
        }
    }
}

public class Solution {
    public bool CarPooling(int[][] trips, int capacity) {
          var dictionary = new SortedDictionary<int, int>();

            foreach (var trip in trips)
            {
                if (!dictionary.ContainsKey(trip[1])) dictionary[trip[1]] = 0;
                if (!dictionary.ContainsKey(trip[2])) dictionary[trip[2]] = 0;
                dictionary[trip[1]] += trip[0]; dictionary[trip[2]] -= trip[0];
            }
            int currentPassennger = 0;
           foreach (var keyval in dictionary)
            {
                currentPassennger += keyval.Value;
                if (currentPassennger > capacity) return false;
            }
            return true;
    }
}

