        sortedKeys.Sort();

        var pattern = string.Concat(sortedKeys) + string.Concat(sortedKeys.AsEnumerable().Reverse());
        var maxItem = charCounts.Values.Max();
        var sample = string.Concat(Enumerable.Repeat(pattern, (maxItem / 2) + 1));

        var result = "";

        foreach (var ch in sample) {
            if (charCounts.ContainsKey(ch) && charCounts[ch] > 0) {
                result += ch;
                charCounts[ch]--;
            }
        }

        return result;
    }
}

public class Solution {
public class Engineer
        {
            public int speed;
            public int efficiency;
            public Engineer(int speed, int efficiency)
            {
                this.speed = speed;
                this.efficiency = efficiency;
            }

        }

        public int MaxPerformance(int n, int[] speed, int[] efficiency, int k)
        {
            List<Engineer> engineers = new();
            for (int i = 0; i < n; i++)
            {
                engineers.Add(new Engineer(speed[i], efficiency[i]));
            }

            engineers = engineers.OrderByDescending(x => x.efficiency).ToList();
            var queue = new PriorityQueue<int, int>();
            long speedTotal = 0, result = 0;
            foreach (var engineer in engineers)
            {
                if (queue.Count > k - 1)
                    speedTotal -= queue.Dequeue();
                queue.Enqueue(engineer.speed, engineer.speed);
                speedTotal += engineer.speed;
                result = Math.Max(result, speedTotal * engineer.efficiency);
            }

            return (int)(result % 1000000007);
        }
}

public class UndergroundSystem
{
    // key: id
    // value: station, time
    private Dictionary<int, (string, int)> checked_in = new();
    // key: start and end station
    // value: total time, count
    private Dictionary<(string, string), (int, int)> backlog = new();
    public UndergroundSystem() { }

    public void CheckIn(int id, string stationName, int t)
    {
        checked_in[id] = (stationName, t);
    }

    public void CheckOut(int id, string stationName, int t)
    {
        (string station, int time) = checked_in[id];
        if (!backlog.TryAdd((station, stationName), (t - time, 1)))
        {
            (int total_time, int count) = backlog[(station, stationName)];
            backlog[(station, stationName)] = (total_time + (t - time), count + 1);
        }
    }

    public double GetAverageTime(string startStation, string endStation)
    {
        (int total_time, int count) = backlog[(startStation, endStation)];
        return (double)total_time / count;
    }
}

public class Solution {
    public int MaxScore(int[] cardPoints, int k) {
     if (k > cardPoints.Length)
            {
                return cardPoints.Sum();
            }
            int res = 0, total = 0;
            int l = 0, r = cardPoints.Length - k;
            for (int i = r; i < cardPoints.Length; i++)
                total += cardPoints[i];
            res = total;
            while (r < cardPoints.Length)
            {
                total += cardPoints[l] - cardPoints[r];
                res = Math.Max(res, total);
                l++;
                r++;
            }
            return res;
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     public int val;
 *     public TreeNode left;
 *     public TreeNode right;
 *     public TreeNode(int val=0, TreeNode left=null, TreeNode right=null) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
public class Solution {
    private int goodNodeCount = 0;
    public void dfs(TreeNode cur, int pathMax) {
        if(cur == null) return;
        if(cur.val >= pathMax) {
            pathMax = cur.val;
            goodNodeCount++;
        }
        dfs(cur.left, pathMax);
        dfs(cur.right, pathMax);

    }
    public int GoodNodes(TreeNode root) {
        dfs(root, int.MinValue);
        return goodNodeCount;
    }
}

public class Solution {
  public int MinReorder(int n, int[][] connections)
        {
            if (connections == null || connections?.Length < 2) return 0;

            Dictionary<int, HashSet<int>> paths = new Dictionary<int, HashSet<int>>();
            List<int>[] graph = new List<int>[n];
            foreach (var connection in connections)
            {
                if (!paths.ContainsKey(connection[0]))
                    paths.Add(connection[0], new HashSet<int>());

                paths[connection[0]].Add(connection[1]);

                if (graph[connection[0]] == null)
                    graph[connection[0]] = new List<int>();
                graph[connection[0]].Add(connection[1]);

                if (graph[connection[1]] == null)
                    graph[connection[1]] = new List<int>();
                graph[connection[1]].Add(connection[0]);
            }
            int cnt = 0;
            HashSet<int> visited = new HashSet<int>();
            DFSMinReorder(graph, 0, paths, visited, ref cnt);
            return cnt;
        }

        private void DFSMinReorder(List<int>[] graph, int u, Dictionary<int, HashSet<int>> paths, HashSet<int> visited, ref int cnt)
        {
            visited.Add(u);

            if (graph[u] != null)
            {
                foreach (var v in graph[u])
                {
                    if (!visited.Contains(v))
                    {
                        if (paths.ContainsKey(u) && paths[u].Contains(v))
                            cnt++;

                        DFSMinReorder(graph, v, paths, visited, ref cnt);
                    }
                }
            }
        }
}

