public class Solution {
    public int MaxFrequency(int[] nums, int k) {
        Array.Sort(nums);

        int left = 0, right = 0;
        var max = 0;
        long totalSum = 0;

        for(right = 0; right < nums.Length; right++) {
            totalSum += nums[right];

            while(nums[right] * (right - left + 1) > totalSum + k) {
                totalSum -= nums[left];
                left++;
            }

            max = Math.Max((right - left + 1), max);
        }

        return max;
    }
}

public class Solution
{
    public int[] MinInterval(int[][] intervals, int[] queries)
    {

        var q = queries.Length;
        var indexDict = new int[q][];
        var index = 0;
        foreach (var query in queries)
        {
            indexDict[index] = new int[2] { query, index };
            index++;
        }
        Array.Sort(indexDict, (a, b) => a[0] - b[0]);
        Array.Sort(intervals, (a, b) => a[0] - b[0]);

        var pq = new PriorityQueue<int[], int>();
        var result = new int[queries.Length];

        index = 0;
        foreach (var query in indexDict)
        {
            var resultIndex = query;
            var calResult = -1;

            while (index < intervals.Length && intervals[index][0] <= resultIndex[0])
            {
                var curr = intervals[index];
                pq.Enqueue(new int[2] { curr[1] - curr[0] + 1, curr[1] }, curr[1] - curr[0] + 1);
                index++;
            }

            while (pq.Count > 0 && pq.Peek()[1] < resultIndex[0])
            {
                pq.Dequeue();
            }
            calResult = pq.Count > 0 ? pq.Peek()[0] : -1;
            result[resultIndex[1]] = calResult;
        }

        return result;

    }
}

public class Solution
{
    //T: O(N)
    public bool MergeTriplets(int[][] triplets, int[] target)
    {
        var hashSet = new HashSet<(int, int)>();

        foreach (var t in triplets)
        {
            if (t[0] > target[0] || t[1] > target[1] || t[2] > target[2])
                continue;

            for (var i = 0; i < t.Length; i++)
            {
                if (t[i] == target[i])
                    hashSet.Add((i, t[i]));
            }
        }

        return hashSet.Count == 3;
    }

}

public class Solution {
    public int CountSubIslands(int[][] grid1, int[][] grid2)
        {
            int r = grid1.Length, c = grid1[0].Length, subIslands = 0;
            for (int i = 0; i < r; i++)
            {
                for (int j = 0; j < c; j++)
                {
                    if (grid2[i][j] == 1 && DfsSubIsLand(grid1, grid2, i, j))
                    {
                        subIslands++;
                    }
                }
            }
            return subIslands;
        }

        private bool DfsSubIsLand(int[][] grid1, int[][] grid2, int r, int c)
        {
            if (r < 0 || c < 0 || r >= grid2.Length || c >= grid2[r].Length || grid2[r][c] == 0) { return true; }

            grid2[r][c] = 0;
            bool stillASubIsland = true;
             stillASubIsland &= DfsSubIsLand(grid1, grid2, r-1, c);
            stillASubIsland &= DfsSubIsLand(grid1, grid2, r, c+1);
            stillASubIsland &= DfsSubIsLand(grid1, grid2, r+1, c);
            stillASubIsland &= DfsSubIsLand(grid1, grid2, r, c-1);
            return stillASubIsland && grid1[r][c] == 1;
        }
}

