public class Solution
{
    public int MinSwaps(string s)
    {
        int open_braces = 0, swaps = 0;
        foreach (var ch in s)
        {
            if (ch == '[')
            {
                open_braces++;
            }
            else
            {
                if (open_braces <= 0)
                {
                    open_braces++;
                    swaps++;
                }
                else
                {
                    open_braces--;
                }
            }
        }

        return swaps;
    }
}

public class Solution {
    public int MinimumDifference(int[] nums, int k) {
        int min = Int32.MaxValue;
        int l = 0, r = k - 1;
        Array.Sort(nums);
        while (r < nums.Length) {
            min = Math.Min(min, nums[r] - nums[l]);
            l++;
            r++;
        }
        return min;
    }
}

public class Solution {
    public int MaxProduct(string s) {
        if(s == null || s.Length < 2)
            return 0;
        if(s.Length == 2)
            return 1;

        int n = s.Length;
        int total = 1 << n;

        List<(int, int)> possible = new List<(int, int)>();

        for(int i = 0; i < total; i++) {
            StringBuilder sb = new StringBuilder();

            for(int j = 0; j < n; j++) {
                if((i & (1 << j)) != 0) {
                    sb.Append(s[j]);
                }
            }

            if(IsPalindrome(sb.ToString())) {
                possible.Add((i, sb.Length));
            }
        }

        int ans = 0;
        for(int i = 0; i < possible.Count; i++) {
            int bitmask = possible[i].Item1;
            int count = possible[i].Item2;
            for(int j = i + 1; j < possible.Count; j++) {
                int bitmask2 = possible[j].Item1;
                int count2 = possible[j].Item2;
                if((bitmask & bitmask2) == 0)
                    ans = Math.Max(ans, count * count2);
            }
        }
        return ans;
    }

    private bool IsPalindrome(string s){
        int i = 0;
        int j = s.Length - 1;
        while(i < j) {
            if(s[i++] != s[j--])
                return false;
        }
        return true;
    }
}

public class DetectSquares {

  private Dictionary<(int x, int y), int> _pointsCounter = new();
    private List<(int x, int y)> _points = new();

    public DetectSquares() { }

    public void Add(int[] point) {
        var p = (point[0], point[1]);
        _points.Add(p);
        _pointsCounter[p] = 1 + _pointsCounter.GetValueOrDefault(p, 0);
    }

    public int Count(int[] point) {
        int px = point[0], py = point[1];
        int result = 0;

        foreach (var (x, y) in _points) {

            if (Math.Abs(px - x) != Math.Abs(py - y)
                || x == px || y == py) {
                continue;
            }
            result += _pointsCounter.GetValueOrDefault((px, y), 0) * _pointsCounter.GetValueOrDefault((x, py), 0);
        }
        return result;
    }
}

